#!/usr/bin/env node
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { minifyCss } from './build-critical-css.mjs';

const root = new URL('../', import.meta.url);
const target = new URL('assets/css/site.css', root);
const sourceFiles = [
  'base.css', 'sections.css', 'phone.css', 'themes.css', 'player-preview.css',
  'app-preview.css', 'app-settings.css', 'app-song-edit.css', 'app-library.css',
  'app-home.css', 'app-motion.css', 'app-header.css', 'app-theme-transition.css',
  'dsp.css', 'app-glass.css', 'desktop.css', 'motion.css',
];

export async function buildStyleBundle() {
  const buffers = await Promise.all(sourceFiles.map(file => readFile(new URL('assets/css/' + file, root))));
  const chunks = [Buffer.from('/* Generated by tools/build-style-bundle.mjs; edit the source stylesheets */\n')];
  buffers.forEach((buffer, index) => {
    // 这些规则依赖文件开头的位置，遇到时应先审查再合并
    if (/^\s*@(import|charset)\b/im.test(buffer.toString('utf8'))) throw new Error('Cannot concatenate @import or @charset in ' + sourceFiles[index]);
    chunks.push(Buffer.from('\n/* Source: assets/css/' + sourceFiles[index] + ' */\n'), Buffer.from(minifyCss(buffer.toString('utf8'))));
    if (index < buffers.length - 1) chunks.push(Buffer.from('\n'));
  });
  return Buffer.concat(chunks);
}

async function main() {
  const args = process.argv.slice(2);
  for (const flag of args) if (flag !== '--check' && flag !== '--stdout') throw new Error('Unknown option: ' + flag);
  const output = await buildStyleBundle();
  if (args.includes('--check')) {
    let current;
    try { current = await readFile(target); } catch (error) { if (error.code !== 'ENOENT') throw error; }
    if (!current || !current.equals(output)) throw new Error('site.css is stale; run node tools/build-style-bundle.mjs');
  } else if (!args.includes('--stdout')) await writeFile(target, output);
  if (args.includes('--stdout')) process.stdout.write(output);
  else console.log('site.css: ' + output.length + ' bytes' + (args.includes('--check') ? ' (current)' : ''));
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch(error => { console.error(error.message); process.exitCode = 1; });
}
